      const maxWidth = full ? this.w * 0.78 : this.w * 0.86;
      this.fit = Math.max(MIN_FIT, Math.min(1, maxWidth / Math.max(1, (this.title.scrollWidth || this.title.textContent.length * this.fontSize))));
