/* === js/master_data/json.js === */
(function () {
  // JSONの2と2.0はPythonの要約では区別される。APIで届いた数値の表記を編集・保存にも引き継ぐ。
  const literals = new WeakMap();
  function parse(text) {
    return JSON.parse(text,function(key,value,context) {
      if (typeof value === 'number' && context?.source && /[.eE]/.test(context.source)) {
        if (!literals.has(this)) literals.set(this,new Map());
        literals.get(this).set(key,context.source);
      }
      return value;
    });
  }
  function stringify(value,space = 2) {
    return JSON.stringify(value,function(key,child) {
      const raw = literals.get(this)?.get(key);
      return raw !== undefined && Object.is(child,Number(raw)) ? JSON.rawJSON(raw) : child;
    },space);
  }
  const clone = value => parse(stringify(value));
  function numberText(holder,key) {
    const raw = holder && literals.get(holder)?.get(key);
    if (raw === undefined || !Object.is(holder[key],Number(raw))) return null;
    return Number.isInteger(holder[key]) ? `${holder[key]}.0` : String(holder[key]);
  }
  function ordered(value,keys) {
    const result = Object.fromEntries(keys.map(key=>[key,value[key]]));
    if (literals.has(value)) literals.set(result,new Map(literals.get(value)));
    return result;
  }
  function forget(holder,key) { literals.get(holder)?.delete(key); }
  window.CatalogJson = {parse,stringify,clone,numberText,ordered,forget};
})();

;

/* === js/master_data/catalog_api.js === */
(function () {
  async function request(path, method = 'GET', body) {
    const options = { method };
    if (body !== undefined) {
      options.headers = { 'Content-Type': 'application/json' };
      options.body = window.CatalogJson.stringify(body,0);
    }
    const response = await fetchWithSession(path, options);
    const data = await response.text().then(window.CatalogJson.parse).catch(() => ({}));
    if (!response.ok) {
      const error = new Error(data.error || `読み込み・保存に失敗しました（${response.status}）`);
      error.status = response.status;
      error.errors = data.errors || {};
      throw error;
    }
    return data;
  }
  const catalog = kind => `/api/catalog/${encodeURIComponent(kind)}`;
  const draft = id => `/api/catalog/drafts/${encodeURIComponent(id)}`;
  const effectRequests = '/api/catalog/effect_requests';
  window.CatalogApi = {
    request,
    effectRequests: () => request(effectRequests),
    createEffectRequest: fields => request(effectRequests, 'POST', fields),
    updateEffectRequest: (id, fields) => request(effectRequests + '/' + id, 'PATCH', fields),
    withdrawEffectRequest: id => request(effectRequests + '/' + id, 'DELETE'),
    reviewEffectRequest: (id, fields) => request(effectRequests + '/' + id + '/review', 'POST', fields),
    overview: () => request('/api/catalog/overview'),
    user: () => request('/api/get_session_user'),
    list: kind => request(catalog(kind)),
    history: (kind, id) => request(`${catalog(kind)}/${encodeURIComponent(id)}/history`),
    references: (kind, id) => request(`${catalog(kind)}/${encodeURIComponent(id)}/references`),
    nextId: (kind, prefix) => request(`${catalog(kind)}/next_id${prefix ? `?prefix=${encodeURIComponent(prefix)}` : ''}`),
    create: (kind, target, prefix) => request(`${catalog(kind)}/drafts`, 'POST', target ? { target_id: target } : prefix ? { id_prefix: prefix } : {}),
    powerPreview: (payload, params) => request('/api/catalog/skill/power_preview', 'POST', {payload, params}),
    textReferences: () => request('/api/catalog/skill/text_references'),
    effectSchemas: () => request('/api/effect_schemas'),
    save: (id, payload) => request(draft(id), 'PUT', { payload }),
    submit: id => request(`${draft(id)}/submit`, 'POST'),
    withdraw: id => request(draft(id), 'DELETE'),
    approve: (id, entryId) => request(`${draft(id)}/approve`, 'POST', entryId ? { entry_id: entryId } : {}),
    reject: (id, reason) => request(`${draft(id)}/reject`, 'POST', { reason }),
    deprecate: (kind, id, deprecated) => request(`${catalog(kind)}/${encodeURIComponent(id)}/deprecate`, 'POST', { deprecated }),
    restore: (kind, id, revision) => request(`${catalog(kind)}/${encodeURIComponent(id)}/restore`, 'POST', { revision }),
  };
})();

;

/* === js/master_data/glossary.js === */
(function () {
  const fields = [
    ['display_name', '表示名', 'text'], ['category', '分類', 'category'],
    ['short', '短い説明', 'textarea'], ['long', '長い説明', 'textarea'],
    ['flavor', 'フレーバー', 'textarea'], ['links', '関連用語', 'array'],
    ['synonyms', '別名', 'array'], ['sort_order', '表示順', 'number'],
  ];
  const categories = ['ルール', 'タイミング', '効果', 'バフ', '状態異常', 'スキルタグ', 'デバフ'];
  const statuses = { published: '公開中', deprecated: '廃止', draft: '下書き', pending: '承認待ち', rejected: '却下' };
  const escape = value => String(value ?? '').replace(/[&<>"']/g, ch => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[ch]));
  function parseJSON(text) {
    let payload;
    try { payload = window.CatalogJson.parse(text); } catch (_) { throw new Error('JSONの書き方を確認してください。'); }
    if (!payload || typeof payload !== 'object' || Array.isArray(payload)) throw new Error('JSONは項目を持つオブジェクトにしてください。');
    return payload;
  }
  function parseField(key, value) {
    if (key === 'links' || key === 'synonyms') {
      if (!Array.isArray(value) || value.some(item => typeof item !== 'string')) throw new Error('文字列の配列にしてください。JSONの節で修正できます。');
      return [...value];
    }
    if (key === 'sort_order') {
      if (!value.trim()) return null;
      if (!/^-?\d+$/.test(value.trim()) || !Number.isSafeInteger(Number(value))) throw new Error('整数で入力してください。空欄は表示順なしです。');
      return Number(value);
    }
    return value;
  }
  function rows(data) {
    return [...(data.entries || []).map(row => ({ ...row, key: `entry:${row.entry_id}`, target_id: row.entry_id, status: row.deprecated ? 'deprecated' : 'published', isDraft: false })),
      ...(data.drafts || []).map(row => ({ ...row, key: `draft:${row.id}`, isDraft: true }))];
  }
  function filter(rows, filters) {
    const query = (filters.search || '').toLocaleLowerCase();
    return rows.filter(row => (filters.status === 'all' || row.status === filters.status)
      && (!filters.category || row.payload.category === filters.category)
      && `${row.target_id} ${row.payload.display_name || ''} ${row.payload.short || ''} ${row.payload.long || ''} ${(row.payload.synonyms || [])}`.toLocaleLowerCase().includes(query));
  }
  const canManageDraft = (row, user) => !!(user.is_app_admin || (user.is_catalog_author && row.created_by === user.user_id));
  const canEdit = (row, user) => row.status !== 'pending' && canManageDraft(row, user);
  function linkCandidates(entries, currentId, chosen, query = '') {
    const needle = query.trim().toLocaleLowerCase();
    return entries.filter(row => !row.deprecated && row.entry_id !== currentId && !chosen.includes(row.entry_id)
      && [row.entry_id, row.payload.display_name, ...(Array.isArray(row.payload.synonyms) ? row.payload.synonyms : [])]
        .some(value => typeof value === 'string' && value.toLocaleLowerCase().includes(needle)));
  }
  function addItem(values, value) {
    const item = typeof value === 'string' ? value.trim() : '';
    return item && !values.includes(item) ? [...values, item] : [...values];
  }
  function removeItem(values, index) {
    return values.filter((_value, position) => !Number.isInteger(index) || position !== index);
  }
  function chips(key, values, entries = []) {
    if (!Array.isArray(values)) return '<p class="cat-field-error">配列の型が違います。JSONの節で修正してください。</p>';
    return values.map((value, index) => {
      const linked = key === 'links' ? entries.find(row => row.entry_id === value) : null;
      const label = key === 'links' ? `${value} ${linked?.payload.display_name || ''}`.trim() : String(value);
      const status = key === 'links' ? !linked ? '未登録' : linked.deprecated ? '廃止' : '' : '';
      return `<span class="cat-chip ${status ? 'is-warning' : ''}"><span class="cat-chip-text">${escape(label)}</span>${status ? `<span class="cat-chip-note">${status}</span>` : ''}<button type="button" class="cat-chip-remove" data-array-remove="${key}" data-index="${index}" aria-label="${escape(label)}を外す">×</button></span>`;
    }).join('');
  }
  function candidateButtons(candidates, selected = -1) {
    return candidates.length ? candidates.map((row, index) => `<button type="button" role="option" tabindex="-1" id="cat-link-option-${index}" data-link-add="${escape(row.entry_id)}" aria-selected="${index === selected}"><code>${escape(row.entry_id)}</code><span>${escape(row.payload.display_name)}</span></button>`).join('') : '<p class="cat-caption" role="status">候補がありません。</p>';
  }
  function arrayField(key, label, value, errors, options) {
    const valid = Array.isArray(value);
    const controls = key === 'links'
      ? `<label class="cat-array-label" for="cat-link-search">関連用語を検索</label><input id="cat-link-search" type="search" role="combobox" aria-autocomplete="list" aria-controls="cat-link-candidates" aria-expanded="false" aria-describedby="cat-error-links" placeholder="ID・名前・別名で検索" value="${escape(options.linkQuery)}" ${valid ? '' : 'disabled'}><div id="cat-link-candidates" class="cat-link-candidates" role="listbox" aria-label="関連用語の候補" hidden></div>`
      : `<div class="cat-alias-entry"><label class="cat-array-label" for="cat-synonym-input">別名を入力<input id="cat-synonym-input" type="text" placeholder="Enterで追加" aria-describedby="cat-error-synonyms" value="${escape(options.aliasInput)}" ${valid ? '' : 'disabled'}></label><button type="button" class="cat-button" data-alias-add ${valid ? '' : 'disabled'}>追加</button></div>`;
    return `<fieldset class="cat-array-field cat-field-wide ${key === 'links' ? 'cat-link-picker' : ''}"><legend>${label}</legend><div id="cat-${key}-chips" class="cat-chips">${chips(key, value, options.entries)}</div>${controls}<span class="cat-field-error" id="cat-error-${key}">${escape(errors[`input:${key}`] || errors[key])}</span></fieldset>`;
  }
  function form(payload, errors = {}, options = {}) {
    return fields.filter(([key])=>!options.section || window.CatalogEditor.keys('glossary',options.section).includes(key)).map(([key, label, type]) => {
      const value = payload[key] ?? (type === 'array' ? [] : '');
      if (type === 'array') return arrayField(key, label, value, errors, options);
      const attrs = `id="cat-field-${key}" data-field="${key}" aria-describedby="cat-error-${key}"`;
      let input;
      if (type === 'category') input = `<select ${attrs}><option value="">選択してください</option>${categories.map(category => `<option ${category === value ? 'selected' : ''}>${escape(category)}</option>`).join('')}</select>`;
      else if (type === 'textarea') input = `<textarea data-catalog-text ${attrs} rows="3">${escape(value)}</textarea>`;
      else input = `<input ${attrs} type="${type}" ${type === 'number' ? 'step="1"' : ''} value="${escape(value)}">`;
      return `<label class="cat-field ${['textarea', 'array'].includes(type) ? 'cat-field-wide' : ''}" for="cat-field-${key}">${escape(label)}${['display_name', 'category'].includes(key) ? ' *' : ''}${input}<span class="cat-field-error" id="cat-error-${key}">${escape(errors[`input:${key}`] || errors[key])}</span></label>`;
    }).join('');
  }
  const defaults = () => ({ display_name: '', category: '', short: '', long: '', flavor: '', links: [], synonyms: [], sort_order: null });
  function detail(payload, { links }) {
    const text = value => Array.isArray(value) ? value.join('、') : value ?? '—';
    return `<dl class="cat-facts"><div><dt>分類</dt><dd>${escape(payload.category)}</dd></div><div><dt>表示順</dt><dd>${escape(text(payload.sort_order))}</dd></div><div class="cat-field-wide"><dt>別名</dt><dd>${escape(text(payload.synonyms))}</dd></div></dl>${['short', 'long', 'flavor'].map(key => `<section class="bo-workspace__card"><h4>${fields.find(field => field[0] === key)[1]}</h4><p class="cat-description">${escape(payload[key] || '—')}</p></section>`).join('')}<section class="bo-workspace__card"><h4>リンク</h4>${links(payload)}</section>`;
  }
  function preview(payload, { links }) {
    return `<section class="bo-workspace__card"><h4>用語のプレビュー</h4><div class="glossary-popup cat-term-preview"><div class="glossary-popup-title">${escape(payload.display_name || '名前未入力')}</div><div class="glossary-popup-category">${escape(payload.category)}</div>${['short', 'long', 'flavor'].map(key => `<div class="glossary-popup-${key}">${escape(payload[key])}</div>`).join('')}</div></section><section class="bo-workspace__card"><h4>リンク先</h4>${links(payload)}</section>`;
  }
  window.CatalogGlossary = { kind: 'glossary', label: '用語', defaults, detail, preview,
    recordMeta: payload => payload.category, recordDescription: payload => payload.short || payload.long,
    externalLink: id => window.Glossary.parseMarkupToHTML(`[[${id}|図鑑の説明を開く]]`),
    jsonHint: '表示名・分類・説明などの項目を編集します。IDはここには含めません。',
    validatePayload() {}, fields, categories, statuses, escape, parseJSON, parseField, rows, filter, canManageDraft, canEdit, form, linkCandidates, addItem, removeItem, chips, candidateButtons };
})();

;

/* === js/master_data/text_tools.js === */
(function () {
  const glossary = window.CatalogGlossary;
  let nextId = 0;
  let closeActive = null;
  const candidates = (entries, currentId, query = '') => glossary.linkCandidates(entries, currentId, [], query);
  function timings(entries) {
    return entries.filter(row => !row.deprecated && row.payload.category === 'タイミング')
      .sort((a, b) => (a.payload.sort_order ?? Infinity) - (b.payload.sort_order ?? Infinity) || a.entry_id.localeCompare(b.entry_id));
  }
  function replace(value, start, end, inserted) {
    return { value: value.slice(0, start) + inserted + value.slice(end), caret: start + inserted.length };
  }
  function insertLink(value, start, end, term, inlineStart = null) {
    const label = inlineStart == null && end > start ? value.slice(start, end) : term.payload.display_name;
    return replace(value, inlineStart ?? start, end, `[[${term.entry_id}|${label}]]`);
  }
  function inlineQuery(value, start, end) {
    if (start !== end) return null;
    const before = value.slice(0, start);
    const match = before.match(/\[\[([^\[\]\n|]*)$/);
    return match ? { start: start - match[0].length, query: match[1] } : null;
  }
  function insertTiming(value, caret, term) {
    const start = caret > 0 ? value.lastIndexOf('\n', caret - 1) + 1 : 0;
    const prefix = value.slice(start).match(/^[ \t]*\([^\n)]*\)[ \t]*[:：][ \t]*/);
    return replace(value, start, start + (prefix?.[0].length || 0), `([[${term.entry_id}|${term.payload.display_name}]]):`);
  }
  function mount(root, { entries, currentId = '' }) {
    const cleanups = [];
    for (const field of root.querySelectorAll('textarea[data-catalog-text]')) {
      const document = field.ownerDocument;
      const id = `cat-text-tools-${++nextId}`;
      const label = field.closest('label');
      const oldFor = label?.getAttribute('for');
      const oldId = field.getAttribute('id');
      const oldAriaLabel = field.getAttribute('aria-label');
      const title = label ? [...label.childNodes].filter(node => node.nodeType === 3).map(node => node.textContent.trim()).join(' ').trim() : '';
      if (oldAriaLabel == null && title) field.setAttribute('aria-label', title);
      if (!field.id) field.id = `${id}-field`;
      // 暗黙のlabelは最初のbuttonを指すため、文章欄を明示して関連を維持する。
      if (label) label.setAttribute('for', field.id);
      const toolbar = document.createElement('div');
      toolbar.className = 'cat-text-tools';
      toolbar.innerHTML = `<div class="cat-text-tools-bar"><button type="button" class="cat-button" data-text-insert aria-expanded="false" aria-controls="${id}-picker">挿入 ▾</button></div><div class="cat-text-picker" id="${id}-picker" hidden><input type="search" aria-label="挿入する用語を検索" placeholder="ID・名前・別名で検索" role="combobox" aria-autocomplete="list" aria-expanded="false" aria-controls="${id}-options"><div class="cat-link-candidates" id="${id}-options" role="listbox" aria-label="挿入する用語の候補"></div></div>`;
      field.before(toolbar);
      const button = toolbar.querySelector('[data-text-insert]');
      const picker = toolbar.querySelector('.cat-text-picker');
      const search = toolbar.querySelector('input');
      const list = toolbar.querySelector('[role="listbox"]');
      let start = 0, end = 0, inlineStart = null, query = '', index = 0, options = [];
      const listeners = [];
      function listen(target, type, handler, capture = false) { target.addEventListener(type, handler, capture); listeners.push([target, type, handler, capture]); }
      function remember() { start = field.selectionStart; end = field.selectionEnd; }
      function close() {
        picker.hidden = true; inlineStart = null;
        if (closeActive === close) closeActive = null;
        toolbar.classList?.remove('is-picking');
        for (const control of [button, search, field]) { control.setAttribute('aria-expanded', 'false'); control.removeAttribute('aria-activedescendant'); }
      }
      function render() {
        const matches = candidates(entries, currentId, query);
        const timingRows = inlineStart == null ? timings(matches) : [];
        const termRows = inlineStart == null ? matches.filter(row => row.payload.category !== 'タイミング') : matches;
        options = [...timingRows, ...termRows];
        index = Math.max(0, Math.min(index, options.length - 1));
        const option = (row, i) => `<button type="button" role="option" tabindex="-1" id="${id}-${i}" data-text-option="${i}" aria-selected="${index === i}"><code>${glossary.escape(row.entry_id)}</code><span>${glossary.escape(row.payload.display_name)}</span></button>`;
        list.innerHTML = options.length ? (timingRows.length ? `<div class="cat-picker-heading">タイミング</div>${timingRows.map(option).join('')}` : '')
          + (termRows.length ? `<div class="cat-picker-heading">用語</div>${termRows.map((row, i) => option(row, i + timingRows.length)).join('')}` : '')
          : '<p class="cat-caption" role="status">候補がありません。</p>';
        for (const control of [search, field]) {
          control.setAttribute('aria-expanded', 'true');
          if (options.length) control.setAttribute('aria-activedescendant', `${id}-${index}`);
          else control.removeAttribute('aria-activedescendant');
        }
      }
      function open(inline = null) {
        if (closeActive && closeActive !== close) closeActive();
        closeActive = close; toolbar.classList?.add('is-picking');
        remember(); inlineStart = inline?.start ?? null; query = inline?.query || ''; index = 0;
        picker.hidden = false; button.setAttribute('aria-expanded', 'true'); search.value = query; render();
        if (!inline) search.focus();
      }
      function apply(result) {
        close(); field.value = result.value; field.focus(); field.setSelectionRange(result.caret, result.caret);
        field.dispatchEvent(new field.ownerDocument.defaultView.Event('input', { bubbles: true }));
      }
      function choose(position) {
        const term = options[position];
        if (term) apply(inlineStart == null && term.payload.category === 'タイミング'
          ? insertTiming(field.value, start, term) : insertLink(field.value, start, end, term, inlineStart));
      }
      listen(button, 'click', event => { event.preventDefault(); if (picker.hidden) open(); else { close(); field.focus(); } });
      // 選択欄へフォーカスが移る前の文章位置を保持する（キーボード操作はblurでも保持）。
      listen(field, 'blur', remember);
      listen(search, 'input', () => { query = search.value; index = 0; render(); });
      listen(list, 'pointerdown', event => event.preventDefault());
      listen(list, 'click', event => {
        const option = event.target.closest('[data-text-option]');
        if (option) { event.preventDefault(); choose(Number(option.dataset.textOption)); }
      });
      listen(field, 'input', event => {
        if (event.isComposing) return;
        const inline = inlineQuery(field.value, field.selectionStart, field.selectionEnd);
        if (inline) open(inline); else close();
      });
      listen(field, 'compositionend', () => {
        const inline = inlineQuery(field.value, field.selectionStart, field.selectionEnd);
        if (inline) open(inline);
      });
      function keydown(event) {
        if (['ArrowLeft', 'ArrowRight', 'Home', 'End', 'Tab'].includes(event.key)) { close(); return; }
        if (picker.hidden || event.isComposing || event.keyCode === 229 || !['ArrowDown', 'ArrowUp', 'Enter', 'Escape'].includes(event.key)) return;
        event.preventDefault(); event.stopPropagation();
        if (event.key === 'Escape') { close(); field.focus(); return; }
        if (event.key === 'Enter') { choose(index); return; }
        if (options.length) index = (index + (event.key === 'ArrowDown' ? 1 : options.length - 1)) % options.length;
        render(); list.querySelector(`[aria-selected="true"]`)?.scrollIntoView({ block: 'nearest' });
      }
      listen(search, 'keydown', keydown); listen(field, 'keydown', keydown);
      listen(document, 'pointerdown', event => {
        if (!picker.hidden && event.target !== button && !button.contains(event.target) && !picker.contains(event.target)) close();
      }, true);
      listen(document, 'keydown', event => {
        if (!picker.hidden && event.key === 'Escape') { event.preventDefault(); event.stopPropagation(); close(); field.focus(); }
      }, true);
      listen(field, 'click', () => close());
      cleanups.push(() => {
        close(); listeners.forEach(([target, type, handler, capture]) => target.removeEventListener(type, handler, capture)); toolbar.remove();
        if (label) { if (oldFor == null) label.removeAttribute('for'); else label.setAttribute('for', oldFor); }
        if (oldId == null) field.removeAttribute('id');
        if (oldAriaLabel == null) field.removeAttribute('aria-label');
      });
    }
    return { destroy() { cleanups.splice(0).forEach(cleanup => cleanup()); } };
  }
  window.CatalogTextTools = { candidates, timings, insertLink, inlineQuery, insertTiming, mount };
})();

;

/* === js/master_data/buff.js === */
(function () {
  const base = window.CatalogGlossary;
  const h = base.escape;
  const fields = [['name', '内部名', 'text'], ['display_name', '表示名', 'text'],
    ['description', '説明', 'textarea'], ['flavor', 'フレーバー', 'textarea'],
    ['default_duration', '持続', 'duration'], ['effect', '効果', 'json']];
  const defaults = () => ({ name: '', display_name: '', description: '', flavor: '', default_duration: 1, effect: {} });
  const duration = value => value === -1 ? '解除まで' : `${value ?? 1}ラウンド`;
  function parseField(key, value) {
    if (key === 'effect') return base.parseJSON(value);
    if (key === 'default_duration') {
      if (!/^-?\d+$/.test(value) || !Number.isSafeInteger(Number(value)) || (Number(value) !== -1 && Number(value) < 1)) throw new Error('-1（解除まで）か1以上の整数で入力してください。');
      return Number(value);
    }
    return value;
  }
  function validatePayload(payload, draft) {
    if (draft.base_revision != null && payload.name !== draft.payload.name) throw new Error('公開済みの内部名は変更できません。');
  }
  function form(payload, errors = {}, options = {}) {
    return fields.filter(([key])=>!options.section || window.CatalogEditor.keys('buff',options.section).includes(key)).map(([key, label, type]) => {
      const value = payload[key] ?? defaults()[key];
      const attrs = `id="cat-field-${key}" data-field="${key}" aria-describedby="cat-error-${key}"`;
      let input;
      if (type === 'duration') input = `<span class="cat-duration-row"><select data-duration-mode aria-label="持続の単位"><option value="rounds" ${value !== -1 ? 'selected' : ''}>ラウンド数</option><option value="permanent" ${value === -1 ? 'selected' : ''}>解除まで</option></select><input ${attrs} type="number" min="1" step="1" aria-label="持続のラウンド数" value="${h(value === -1 ? '' : value)}" ${value === -1 ? 'disabled' : ''}></span>`;
      else if (type === 'json') input = `<textarea ${attrs} class="cat-effect-source" spellcheck="false" rows="6">${h(options.effectText ?? JSON.stringify(value, null, 2))}</textarea>`;
      else if (type === 'textarea') input = `<textarea data-catalog-text ${attrs} rows="3">${h(value)}</textarea>`;
      else input = `<input ${attrs} type="text" value="${h(value)}" ${key === 'name' && options.published ? 'readonly' : ''}>`;
      return `<label class="cat-field ${type === 'textarea' || type === 'json' ? 'cat-field-wide' : ''}">${h(label)}${key === 'name' ? ' *' : ''}${input}<span class="cat-field-error" id="cat-error-${key}">${h(errors[`input:${key}`] || errors[key])}</span>${key === 'name' && options.published ? '<small>公開済みの内部名は変更できません。</small>' : ''}</label>`;
    }).join('');
  }
  function preview(payload) {
    const markup = value => window.Glossary?.parseMarkupToHTML(String(value || '')) ?? h(value);
    return `<section class="bo-workspace__card"><h4>バフのプレビュー</h4><details class="buff-accordion" open><summary class="buff-summary"><div class="buff-summary-body"><span class="buff-name">${h(payload.display_name || payload.name || '名前未入力')}</span><div class="buff-meta">${h(duration(payload.default_duration))}</div></div><span class="buff-arrow">▼</span></summary><div class="buff-body"><div class="buff-desc-row">${markup(payload.description)}</div>${payload.flavor ? `<div class="buff-flavor-row">${markup(payload.flavor)}</div>` : ''}</div></details></section>`;
  }
  window.CatalogBuff = { ...base, kind: 'buff', label: 'バフ', categories: [], fields, defaults, duration,
    parseField, validatePayload, form, preview, detail: payload => `<dl class="cat-facts"><div><dt>内部名</dt><dd>${h(payload.name)}</dd></div><div><dt>持続</dt><dd>${h(duration(payload.default_duration))}</dd></div></dl>${preview(payload)}`,
    recordMeta: payload => duration(payload.default_duration), recordDescription: payload => payload.description,
    externalLink: () => '', jsonHint: '内部名・表示名・説明・持続・効果などを編集します。IDは含めません。',
    filter(rows, filters) {
      const needle = (filters.search || '').toLocaleLowerCase();
      return rows.filter(row => (filters.status === 'all' || row.status === filters.status)
        && [row.target_id, row.payload.name, row.payload.display_name, row.payload.description, row.payload.flavor].join(' ').toLocaleLowerCase().includes(needle));
    },
  };
})();

;

/* === js/master_data/resources.js === */
(function () {
  const base = window.CatalogBuff;
  const h = window.CatalogGlossary.escape;
  const common = [['name', '名前', 'text'], ['description', '説明', 'textarea'], ['flavor', 'フレーバー', 'textarea'], ['effect', '効果', 'json']];
  const definitions = {
    item: {label:'アイテム', fields:[common[0], ['consumable','消耗','boolean'], ['usable','使用可能','boolean'], ['round_limit','ラウンド制限','duration'], ...common.slice(1)],
      defaults:{name:'',description:'',flavor:'',consumable:false,usable:false,round_limit:-1,effect:{}}},
    passive: {label:'特殊パッシブ', fields:[common[0], ['cost','取得コスト','number'], ...common.slice(1)],
      defaults:{name:'',cost:0,description:'',flavor:'',effect:{}}},
    radiance: {label:'輝化スキル', fields:[common[0], ['cost','取得コスト','number'], ['duration','持続','duration'], ['granted_tag_ids','付与タグ','tags'], ...common.slice(1)],
      defaults:{name:'',cost:0,description:'',flavor:'',effect:{},duration:-1,granted_tag_ids:[]}},
  };
  function integer(value) {
    if (!/^-?\d+$/.test(value) || !Number.isSafeInteger(Number(value))) throw new Error('整数で入力してください。');
    return Number(value);
  }
  const duration = (key, value) => value === -1 ? key === 'round_limit' ? '制限なし' : '解除まで' : `${value}ラウンド`;
  const facts = rows => `<dl class="cat-facts">${rows.map(([label,value])=>`<div><dt>${h(label)}</dt><dd>${h(value)}</dd></div>`).join('')}</dl>`;
  function tagsField(value, errors, input) {
    const valid = Array.isArray(value) && value.every(tag=>typeof tag === 'string');
    return `<fieldset class="cat-array-field cat-field-wide"><legend>付与タグ</legend><div id="cat-granted_tag_ids-chips" class="cat-chips">${valid ? base.chips('granted_tag_ids',value) : '<p class="cat-field-error">文字列の配列にしてください。JSONの節で修正できます。</p>'}</div><div class="cat-alias-entry"><label class="cat-array-label">タグを入力<input id="cat-granted-tag-input" value="${h(input)}" placeholder="Enterで追加" ${valid ? '' : 'disabled'}></label><button type="button" class="cat-button" data-tag-add="true" ${valid ? '' : 'disabled'}>追加</button></div><span class="cat-field-error" id="cat-error-granted_tag_ids">${h(errors['input:granted_tag_ids'] || errors.granted_tag_ids)}</span></fieldset>`;
  }
  function make(kind, definition) {
    const {label,fields} = definition;
    const defaults = () => JSON.parse(JSON.stringify(definition.defaults));
    function parseField(key, value) {
      if (key === 'effect') return base.parseJSON(value);
      const type = fields.find(field=>field[0]===key)?.[2];
      if (type === 'boolean') {
        if (!['true','false'].includes(value)) throw new Error('はい・いいえから選んでください。');
        return value === 'true';
      }
      if (type === 'number' || type === 'duration') return integer(value);
      if (type === 'tags') return window.CatalogGlossary.parseField('synonyms',value);
      return value;
    }
    function form(payload, errors = {}, options = {}) {
      return fields.filter(([key])=>!options.section || window.CatalogEditor.keys(kind,options.section).includes(key)).map(([key,title,type])=>{
        const value = payload[key] ?? defaults()[key];
        if (type === 'tags') return tagsField(value,errors,options.tagInput || '');
        const attrs = `id="cat-field-${key}" data-field="${key}" aria-describedby="cat-error-${key}"`;
        let control;
        if (type === 'boolean') control = `<select ${attrs}><option value="true" ${value === true ? 'selected' : ''}>はい</option><option value="false" ${value === false ? 'selected' : ''}>いいえ</option></select>`;
        else if (type === 'duration') control = `<span class="cat-duration-row"><select data-duration-mode data-duration-field="${key}" aria-label="${title}の単位"><option value="rounds" ${value !== -1 ? 'selected' : ''}>ラウンド数</option><option value="permanent" ${value === -1 ? 'selected' : ''}>${key === 'round_limit' ? '制限なし' : '解除まで'}</option></select><input ${attrs} aria-label="${title}のラウンド数" type="number" step="1" value="${h(value === -1 ? '' : value)}" ${value === -1 ? 'disabled' : ''}></span>`;
        else if (type === 'textarea') control = `<textarea data-catalog-text ${attrs} rows="3">${h(value)}</textarea>`;
        else if (type === 'json') control = `<textarea ${attrs} class="cat-effect-source" spellcheck="false" rows="6">${h(options.effectText ?? JSON.stringify(value,null,2))}</textarea>`;
        else control = `<input ${attrs} type="${type === 'number' ? 'number' : 'text'}" ${type === 'number' ? 'step="1"' : ''} value="${h(value)}">`;
        return `<label class="cat-field ${['textarea','json'].includes(type) ? 'cat-field-wide' : ''}">${h(title)}${key === 'name' ? ' *' : ''}${control}<span class="cat-field-error" id="cat-error-${key}">${h(errors['input:'+key] || errors[key])}</span></label>`;
      }).join('');
    }
    function metadata(payload) {
      if (kind === 'item') return `${payload.usable ? '使用可能' : '使用不可'} · ${payload.consumable ? '消耗' : '消耗なし'} · ${duration('round_limit',payload.round_limit ?? -1)}`;
      return `取得コスト ${payload.cost ?? 0}${kind === 'radiance' ? ' · '+duration('duration',payload.duration ?? -1) : ''}`;
    }
    function preview(payload) {
      const details = fields.filter(([_key,_title,type])=>['boolean','number','duration'].includes(type)).map(([key,title,type])=>[title,type === 'boolean' ? payload[key] ? 'はい' : 'いいえ' : type === 'duration' ? duration(key,payload[key] ?? -1) : payload[key] ?? 0]);
      const markup = value => window.Glossary?.parseMarkupToHTML(String(value || '')) ?? h(value);
      return `<section class="bo-workspace__card"><h4>${label}のプレビュー</h4><details class="buff-accordion" open><summary class="buff-summary"><div class="buff-summary-body"><span class="buff-name">${h(payload.name || '名前未入力')}</span><div class="buff-meta">${h(metadata(payload))}</div></div><span class="buff-arrow">▼</span></summary><div class="buff-body"><div class="buff-desc-row">${markup(payload.description)}</div>${payload.flavor ? `<div class="buff-flavor-row">${markup(payload.flavor)}</div>` : ''}</div></details>${facts(details)}${kind === 'radiance' ? `<div class="cat-chips">${Array.isArray(payload.granted_tag_ids) ? payload.granted_tag_ids.map(tag=>`<span class="cat-chip">${h(tag)}</span>`).join('') : '<span class="cat-field-error">付与タグは文字列の配列で入力してください。</span>'}</div>` : ''}</section>`;
    }
    return {...base,kind,label,fields,defaults,parseField,form,preview,detail:preview,recordMeta:metadata,validatePayload() {},
      jsonHint:'名前・説明・効果などを編集します。IDは含めません。',
    };
  }
  const models = Object.fromEntries(Object.entries(definitions).map(([kind,definition])=>[kind,make(kind,definition)]));
  const summonFields = [['name','名前'],['hp','HP'],['maxHp','最大HP'],['mp','MP'],['maxMp','最大MP'],['initial_skill_ids','最初から持つスキル'],['hidden_skills','秘匿スキル'],['SPassive','特殊パッシブ'],['radiance_skills','輝化スキル'],['inventory','所持アイテム'],['summon_duration_mode','持続の種類'],['summon_duration','持続ラウンド'],['allow_duplicate_same_team','同陣営の重複'],['params','能力値'],['tag_ids','タグ'],['disabled_tag_ids','無効なタグ'],['special_buffs','バフ'],['flags','設定']];
  function summonPreview(payload, options = {}) {
    const skills = Array.isArray(payload.initial_skill_ids) ? payload.initial_skill_ids : [];
    const params = Array.isArray(payload.params) ? payload.params.filter(row=>row && typeof row === 'object') : [];
    const lasting = payload.summon_duration_mode === 'permanent' ? '解除まで' : `${payload.summon_duration ?? 0}ラウンド`;
    return `<section class="bo-workspace__card"><h4>召喚テンプレートのプレビュー</h4><h3>${h(payload.name || '名前未入力')}</h3>${facts([['HP',`${payload.hp ?? 0} / ${payload.maxHp ?? 0}`],['MP',`${payload.mp ?? 0} / ${payload.maxMp ?? 0}`],['召喚の持続',lasting]])}</section><section class="bo-workspace__card"><h4>最初から持つスキル</h4>${skills.length ? `<ul class="cat-effect-list">${skills.map(id=>{const row=options.skillEntries?.find(row=>row.entry_id===id);return `<li><code>${h(id)}</code> ${h(row?.payload.デフォルト名称 || '公開名なし')}</li>`;}).join('')}</ul>` : '<p class="cat-caption">なし</p>'}</section><section class="bo-workspace__card"><h4>能力値</h4>${facts(params.map(row=>[row.label,row.value]))}</section>`;
  }
  models.summon = {...base,kind:'summon',label:'召喚テンプレート',form:null,fields:summonFields,
    defaults:()=>({name:'',hp:0,maxHp:0,mp:0,maxMp:0,initial_skill_ids:[],hidden_skills:[],SPassive:[],radiance_skills:[],inventory:{},summon_duration_mode:'permanent',summon_duration:0,allow_duplicate_same_team:true,params:[],tag_ids:[],disabled_tag_ids:[],special_buffs:[],flags:{}}),
    validatePayload() {},preview:summonPreview,detail:summonPreview,recordMeta:payload=>`HP ${payload.hp ?? 0} / MP ${payload.mp ?? 0}`,
    recordDescription:payload=>`${payload.summon_duration_mode === 'permanent' ? '解除まで' : `${payload.summon_duration ?? 0}ラウンド`} · スキル ${Array.isArray(payload.initial_skill_ids) ? payload.initial_skill_ids.length : 0}件`,jsonHint:'召喚テンプレートのJSONを編集します。baseName（ID）は含めません。',
  };
  window.CatalogResources = models;
})();

;

